import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-accounting-module-basics";

// A menu click only proves the menu item existed. Wait until the app has really navigated (the URL changes —
// until then the OLD view is still on screen and would satisfy any "is a view visible" check), let the new view
// render, report where we landed, and keep a screenshot of the finished screen.
async function landed(page: Page, ref: string, file: string, urlBefore: string): Promise<string> {
  await page.waitForURL((u) => u.toString() !== urlBefore, { timeout: 30000 });
  await page
    .locator(".o_action_manager .o_view_controller, .o_action_manager .o_action")
    .first()
    .waitFor({ state: "visible", timeout: 30000 });
  await page.locator(".o_loading_indicator, .o_loading").waitFor({ state: "hidden", timeout: 15000 }).catch(() => {});
  const raw = await page.locator(".o_control_panel").first().innerText().catch(() => "");
  const where = raw.split("\n").join(" ").replace(/ +/g, " ").trim();
  console.log("[landed] " + ref + " | title: " + (await page.title()) + " | " + where.slice(0, 110));
  // The browser tab title names the screen we are on — fail if a menu opened the wrong one.
  const expected =
    ref === "Customers > Payments" ? "Customer Payments"
    : ref === "Vendors > Payments" ? "Vendor Payments"
    : (ref.split(" > ").pop() as string);
  await expect(page, "landed on " + ref).toHaveTitle(new RegExp(expected));
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: SHOT_DIR + "/" + file });
  return where;
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

